def get_positive_int(prompt, max_attempts=3, error_msg="Invalid input, try again!"):
    results = []
    attempts = 0
    while attempts < max_attempts:
        try:
            value = int(input(prompt))
            if value > 0:
                results.append(value)   # use list method append as described
                return results
            else:
                print(error_msg)
        except ValueError:
            print(error_msg)
        attempts += 1
    # No valid input after allowed attempts
    return None
```

